@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&display=swap');
:root{--bg:#07111d;--panel:#0b1926;--panel2:#0e202e;--cyan:#49f4dc;--orange:#ff8a52;--white:#eff7f5;--muted:#77909c;--line:rgba(127,194,194,.17);--font:'Barlow Condensed',Impact,sans-serif;--mono:'DM Mono',monospace}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--white)}body{font-family:var(--font);-webkit-font-smoothing:antialiased}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100dvh;min-height:520px;overflow:hidden;background:#07111d}#game{position:absolute;inset:0;width:100%;height:100%;display:block;opacity:0;transition:opacity .5s}.scanlines{position:absolute;inset:0;pointer-events:none;z-index:2;opacity:.11;background:repeating-linear-gradient(0deg,transparent 0 3px,rgba(0,0,0,.26) 4px)}.topbar{position:absolute;z-index:8;top:0;left:0;right:0;height:72px;padding:0 5.1%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(115,185,190,.12);background:linear-gradient(180deg,rgba(5,15,24,.82),transparent)}.brand{display:flex;align-items:center;gap:11px;color:var(--white);text-decoration:none;font-size:19px;font-weight:800;letter-spacing:1.9px;line-height:.85}.brand-light{font-weight:500;color:#9bb3b7}.brand small{display:block;color:#77909c;font-family:var(--mono);font-size:8px;letter-spacing:2px;margin-top:8px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;background:var(--cyan);color:#082024;font-size:24px;clip-path:polygon(0 0,100% 0,100% 72%,72% 100%,0 100%);font-style:italic}.top-status{font:10px var(--mono);letter-spacing:1.4px;color:#8da5a9}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#55f2be;box-shadow:0 0 10px #55f2be;margin-right:8px}.divider{padding:0 12px;color:#46606c}.icon-btn{border:1px solid var(--line);background:rgba(6,19,29,.45);padding:9px 13px;color:var(--cyan);font-size:14px;cursor:pointer}.icon-btn span{font:9px var(--mono);letter-spacing:1px;margin-left:6px;color:#9eb6b8}
.screen{position:absolute;inset:0;z-index:5}.menu-screen{display:flex;align-items:center;padding:80px 5.1% 48px;overflow:auto;background:linear-gradient(90deg,rgba(5,15,24,.98) 0%,rgba(5,15,24,.91) 53%,rgba(5,15,24,.55) 100%),linear-gradient(0deg,rgba(5,15,24,.4),transparent)}.menu-content{width:min(790px,72vw);position:relative;z-index:1}.eyebrow{font:10px var(--mono);letter-spacing:2.2px;color:var(--cyan);margin:0 0 16px}.eyebrow-line{display:inline-block;width:25px;height:1px;background:var(--cyan);vertical-align:middle;margin-right:9px}.menu-content h1{font-size:clamp(54px,7vw,86px);font-weight:900;line-height:.78;letter-spacing:1px;margin:0;text-shadow:0 4px 30px rgba(0,0,0,.25)}.menu-content h1 span{color:var(--cyan)}.intro{max-width:430px;color:#9aafb3;font-size:16px;line-height:1.35;margin:19px 0 25px;font-weight:400}.menu-section-title{font:10px var(--mono);letter-spacing:1.3px;color:#d9e8e7;margin-bottom:10px}.menu-section-title>span{color:var(--cyan);margin-right:8px}.mode-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.mode-card{position:relative;min-height:82px;padding:13px 10px 10px 47px;text-align:left;background:rgba(12,30,42,.69);border:1px solid var(--line);cursor:pointer;transition:.18s}.mode-card:hover,.mode-card.selected{background:rgba(25,65,68,.68);border-color:var(--cyan);box-shadow:inset 0 0 22px rgba(73,244,220,.06)}.mode-icon{position:absolute;left:14px;top:13px;color:var(--cyan);font-size:24px}.mode-name{display:block;font-weight:700;font-size:16px;letter-spacing:.6px}.mode-desc{display:block;color:#91a7ad;font-size:12px;margin-top:3px}.mode-tag{position:absolute;right:9px;top:10px;font:8px var(--mono);color:#617e86;letter-spacing:.5px}.map-title{margin-top:19px}.map-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.map-card{height:88px;position:relative;padding:0 10px 9px;text-align:left;overflow:hidden;cursor:pointer;background:#0b1926;border:1px solid var(--line);transition:.18s}.map-card:hover,.map-card.selected{border-color:var(--cyan)}.map-preview{position:absolute;inset:0 0 0;height:100%;overflow:hidden;opacity:.7}.map-preview:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,#0b1926 0%,rgba(9,23,33,.52) 57%,rgba(9,23,33,.12))}.map-preview i{position:absolute;bottom:15px;width:22px;background:#1f7182;border:1px solid #39b9b6;box-shadow:0 0 15px #1c8994}.map-preview i:nth-child(1){left:16%;height:34px}.map-preview i:nth-child(2){left:46%;height:54px;width:27px}.map-preview i:nth-child(3){right:12%;height:39px;width:30px}.neon-preview{background:radial-gradient(ellipse at 50% 120%,#125364,#121636 53%,#06111c)}.neon-preview i{background:#176376}.dune-preview{background:linear-gradient(#8d7a46,#c17f40 50%,#453421)}.dune-preview i{background:#90764d;border-color:#e4b46c;box-shadow:0 0 14px #c38643}.frost-preview{background:linear-gradient(#416f82,#86b7b9 48%,#23404a)}.frost-preview i{background:#538a94;border-color:#8ce5e4;box-shadow:0 0 14px #6dd6d7}.map-name,.map-sub{position:relative;z-index:1;display:block}.map-name{margin-top:48px;font-size:15px;font-weight:700;letter-spacing:.7px}.map-sub{font:8px var(--mono);color:#9db6bb;letter-spacing:.7px;margin-top:2px}.map-check{display:none;position:absolute;right:9px;top:8px;z-index:1;color:var(--cyan);font-size:14px}.map-card.selected .map-check{display:block}.start-btn{display:flex;align-items:center;justify-content:space-between;width:100%;margin-top:15px;padding:0 17px;height:48px;border:0;background:var(--cyan);color:#07191e;cursor:pointer;font-size:17px;font-weight:800;letter-spacing:1px;transition:.2s;clip-path:polygon(0 0,calc(100% - 14px) 0,100% 14px,100% 100%,0 100%)}.start-btn:hover{background:#8fffee;transform:translateY(-1px);box-shadow:0 7px 28px rgba(73,244,220,.2)}.start-btn b{font-size:24px;font-weight:500}.controls-hint{margin:12px 0 0;text-align:center;color:#718993;font:8px var(--mono);letter-spacing:.4px}.controls-hint span{padding:0 5px;color:var(--cyan)}kbd{display:inline-block;padding:2px 4px;border:1px solid #3e5860;border-radius:2px;color:#bad0ce;font:8px var(--mono);margin:0 2px}.menu-side{position:absolute;right:6%;top:18%;width:29%;height:70%;display:flex;align-items:center;justify-content:center;pointer-events:none}.side-orbit{position:absolute;border:1px solid rgba(73,244,220,.23);border-radius:50%;width:min(34vw,420px);height:min(34vw,420px);transform:rotate(-25deg) scaleY(.66)}.orbit-two{width:min(27vw,330px);height:min(27vw,330px);border-color:rgba(255,138,82,.35);transform:rotate(38deg) scaleY(.64)}.side-core{width:125px;height:125px;border:1px solid rgba(73,244,220,.6);display:grid;place-items:center;color:var(--cyan);font-size:90px;font-style:italic;font-weight:800;position:relative;background:radial-gradient(circle,rgba(73,244,220,.13),transparent 68%);text-shadow:0 0 25px rgba(73,244,220,.5)}.side-core span{font-size:18px;position:absolute;right:14px;top:17px;color:#ff9b66}.side-label{position:absolute;right:2%;top:10%;font-size:17px;font-weight:800;line-height:.95;letter-spacing:1px}.side-label span{color:var(--cyan);font-size:10px;letter-spacing:2px}.side-coords{position:absolute;left:5%;bottom:7%;font:9px/1.7 var(--mono);letter-spacing:1px;color:#71929a}
.footer{position:absolute;z-index:8;bottom:0;left:0;right:0;padding:12px 5.1%;display:flex;justify-content:space-between;color:#607983;font:8px var(--mono);letter-spacing:1.1px;pointer-events:none}.hidden{display:none!important}
/* In-game HUD */
.hud{position:absolute;inset:0;z-index:4;pointer-events:none}.hud-left,.hud-right{position:absolute;top:86px;padding:13px 16px;background:linear-gradient(90deg,rgba(4,14,21,.78),rgba(4,14,21,.25));border-left:2px solid var(--cyan);min-width:145px}.hud-left{left:5%}.hud-right{right:5%;border-left:0;border-right:2px solid var(--cyan);text-align:right;background:linear-gradient(270deg,rgba(4,14,21,.78),rgba(4,14,21,.25))}.hud-label,.score-label,.health-row,.reload-note{font:8px var(--mono);letter-spacing:1.3px;color:#89a6aa}.hud-map{font-size:20px;font-weight:700;letter-spacing:.6px}.wave-box{margin-top:11px;display:flex;align-items:center;gap:10px;color:#9db2b6;font:9px var(--mono)}.wave-box b{color:var(--orange);font:20px var(--font)}.score{font:27px var(--mono);color:var(--cyan);letter-spacing:2px}.health-row{display:flex;align-items:center;justify-content:flex-end;gap:7px;margin-top:6px}.health-track{width:78px;height:5px;background:#263a40}.health-track i{display:block;width:100%;height:100%;background:#ff8a52;transition:width .2s}.health-row b{color:#d8e4df;font-weight:400}.ammo{margin-top:12px;color:var(--white);font:26px var(--mono)}.ammo small{color:#718a92;font-size:12px}.ammo-label{display:block;color:#89a6aa;font:8px var(--mono);letter-spacing:1.2px}.hud-center{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:100%;height:100%;pointer-events:none}.objective{position:absolute;top:28px;left:0;right:0;text-align:center;color:#d8e8e5;font:10px var(--mono);letter-spacing:2px;text-shadow:0 2px 5px #000}.timer{position:absolute;top:52px;left:0;right:0;text-align:center;color:var(--orange);font:29px var(--mono);text-shadow:0 2px 8px #000}.crosshair{position:absolute;left:50%;top:50%;width:23px;height:23px;transform:translate(-50%,-50%);filter:drop-shadow(0 0 4px rgba(0,0,0,.8));transition:transform .08s}.crosshair i{position:absolute;width:2px;height:7px;background:var(--cyan)}.crosshair i:nth-child(1){left:10px;top:0}.crosshair i:nth-child(2){left:10px;bottom:0}.crosshair i:nth-child(3){top:8px;left:0;transform:rotate(90deg)}.crosshair i:nth-child(4){top:8px;right:0;transform:rotate(90deg)}.crosshair b{position:absolute;left:9px;top:9px;width:4px;height:4px;border:1px solid var(--cyan);border-radius:50%}.crosshair.firing{transform:translate(-50%,-50%) scale(1.45)}.hit-marker{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) scale(.6);font:26px var(--font);color:#fff;opacity:0;text-shadow:0 0 9px var(--cyan)}.hit-marker.show{opacity:1;transform:translate(-50%,-50%) scale(1);transition:.08s}.toast{position:absolute;top:calc(50% + 45px);width:100%;text-align:center;color:var(--cyan);font:10px var(--mono);letter-spacing:1.5px;text-shadow:0 2px 4px #000}.pause-btn{position:absolute;top:24px;right:5%;width:34px;height:34px;border:1px solid rgba(255,255,255,.3);background:rgba(7,17,29,.5);font-size:16px;pointer-events:auto;cursor:pointer}.reload-note{position:absolute;right:5%;bottom:30px}.mobile-controls{display:none;pointer-events:auto}.damage-flash{position:absolute;inset:0;z-index:3;pointer-events:none;box-shadow:inset 0 0 0 0 rgba(255,55,61,0);transition:box-shadow .12s}.damage-flash.flash{box-shadow:inset 0 0 90px 20px rgba(255,55,61,.55)}
.modal-screen{display:grid;place-items:center;background:rgba(3,11,17,.72);backdrop-filter:blur(7px);z-index:7}.modal-card{width:min(460px,90vw);padding:35px;background:linear-gradient(145deg,#102531,#091620);border:1px solid rgba(73,244,220,.35);box-shadow:0 25px 100px #000}.modal-card h2{font-size:46px;line-height:.9;margin:0 0 13px}.modal-card>p:not(.eyebrow){color:#9bb0b3;margin:0 0 20px;font-size:16px}.text-btn{display:block;width:100%;margin-top:13px;background:transparent;border:0;color:#8ba3a9;font:9px var(--mono);letter-spacing:1.5px;padding:9px;cursor:pointer}.text-btn:hover{color:var(--cyan)}.result-stats{display:grid;grid-template-columns:repeat(3,1fr);padding:15px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.result-stats span{display:block;color:#8ba2a8;font:8px var(--mono);letter-spacing:.7px}.result-stats b{display:block;margin-top:5px;color:var(--cyan);font:18px var(--mono)}.orientation-tip{display:none}
@media(max-width:850px){.menu-side{right:2%;opacity:.55;width:25%}.menu-content{width:min(700px,78vw)}.mode-tag{display:none}.top-status{font-size:8px}.side-label{font-size:12px}}
@media(max-width:620px){#game-shell{min-height:440px}.topbar{height:58px;padding:0 17px}.brand{font-size:16px}.brand-mark{width:30px;height:30px;font-size:21px}.top-status{display:none}.icon-btn{padding:7px 9px}.menu-screen{padding:74px 17px 48px;align-items:flex-start;background:linear-gradient(90deg,rgba(5,15,24,.96),rgba(5,15,24,.8)),linear-gradient(0deg,rgba(5,15,24,.4),transparent)}.menu-content{width:100%;padding-bottom:10px}.menu-content h1{font-size:56px}.intro{font-size:14px;margin:13px 0 17px;max-width:310px}.menu-section-title{font-size:9px}.mode-grid{gap:5px}.mode-card{padding:10px 5px 8px;min-height:82px;text-align:center}.mode-icon{position:static;display:block;font-size:18px;line-height:18px;margin-bottom:4px}.mode-name{font-size:12px;line-height:1}.mode-desc{font-size:10px;line-height:1.1;margin-top:4px}.map-title{margin-top:14px}.map-grid{gap:5px}.map-card{height:77px;padding:0 5px 7px}.map-name{font-size:12px;margin-top:45px}.map-sub{font-size:7px;letter-spacing:0}.map-preview i{bottom:12px}.start-btn{height:45px;margin-top:12px;font-size:15px}.controls-hint{font-size:7px;white-space:nowrap;letter-spacing:0;margin-top:9px}.controls-hint kbd{font-size:7px;padding:2px}.menu-side{right:-19%;top:13%;width:60%;height:35%;opacity:.25}.side-orbit{width:220px;height:220px}.side-core{width:75px;height:75px;font-size:54px}.side-label,.side-coords{display:none}.footer{padding:9px 17px;font-size:7px}.footer span:nth-child(2){display:none}.hud-left,.hud-right{top:68px;padding:9px 10px;min-width:118px}.hud-left{left:12px}.hud-right{right:12px}.hud-label,.score-label{font-size:7px}.hud-map{font-size:16px}.wave-box{margin-top:7px;font-size:8px}.wave-box b{font-size:17px}.score{font-size:21px}.health-row{font-size:7px;gap:4px}.health-track{width:54px}.ammo{font-size:21px;margin-top:7px}.ammo-label{font-size:7px}.pause-btn{top:17px;right:14px;width:30px;height:30px}.objective{top:18px;font-size:8px;letter-spacing:1px}.timer{top:36px;font-size:23px}.reload-note{display:none}.mobile-controls{display:block;position:absolute;inset:0}.joystick{position:absolute;left:23px;bottom:42px;width:105px;height:105px;border:1px solid rgba(180,240,230,.38);border-radius:50%;background:rgba(5,18,26,.35);touch-action:none}.joy-knob{position:absolute;left:50%;top:50%;width:43px;height:43px;transform:translate(-50%,-50%);border-radius:50%;background:rgba(73,244,220,.52);border:1px solid rgba(180,255,245,.75);box-shadow:0 0 18px rgba(73,244,220,.2)}.fire-btn{position:absolute;right:24px;bottom:44px;width:78px;height:78px;border:1px solid rgba(255,138,82,.82);border-radius:50%;background:rgba(117,45,36,.48);color:#ffb18e;display:grid;place-content:center;touch-action:none}.fire-btn span{font-size:27px;line-height:27px}.fire-btn small{font:8px var(--mono);letter-spacing:1px}.reload-btn{position:absolute;right:39px;bottom:134px;width:43px;height:43px;border-radius:50%;border:1px solid rgba(255,255,255,.38);background:rgba(5,18,26,.5);font-size:22px;touch-action:none}.crosshair{transform:translate(-50%,-50%) scale(.85)}.modal-card{padding:25px}.modal-card h2{font-size:39px}.orientation-tip{display:none!important}}
@media(max-height:650px) and (min-width:621px){.menu-screen{padding-top:68px;padding-bottom:38px}.menu-content h1{font-size:58px}.intro{margin:10px 0 14px}.mode-card{min-height:70px}.map-card{height:74px}.map-name{margin-top:39px}.map-title{margin-top:13px}.start-btn{height:42px;margin-top:10px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d', { alpha: false });
  const $ = (id) => document.getElementById(id);
  const maps = {
    neon: { name:'NEON DISTRICT', top:'#10172e', horizon:'#342b61', floor:'#17202c', wall:['#173c50','#1d5360','#234b63'], glow:'#4cf5dc', grid:'#1e5363', layout:[
      '################', '#..............#', '#..##.....##...#', '#..............#', '#......#.......#', '#......#..##...#', '#..............#', '#.###..........#', '#..............#', '#....##........#', '#..............#', '#...#......##..#', '#..............#', '#.....##.......#', '#..............#', '################'] },
    dune: { name:'DUNE OUTPOST', top:'#514332', horizon:'#ba8b53', floor:'#53432d', wall:['#876742','#b38b51','#75583d'], glow:'#ffd078', grid:'#8c7148', layout:[
      '################', '#..............#', '#..##.....##...#', '#..............#', '#......#.......#', '#......#..##...#', '#..............#', '#.###..........#', '#..............#', '#....##........#', '#..............#', '#...#......##..#', '#..............#', '#.....##.......#', '#..............#', '################'] },
    frost: { name:'FROST LAB', top:'#192f46', horizon:'#76aebb', floor:'#263d49', wall:['#52828c','#639ca0','#47717f'], glow:'#a3f4f2', grid:'#557f86', layout:[
      '################', '#..............#', '#..##.....##...#', '#..............#', '#......#.......#', '#......#..##...#', '#..............#', '#.###..........#', '#..............#', '#....##........#', '#..............#', '#...#......##..#', '#..............#', '#.....##.......#', '#..............#', '################'] }
  };
  const state = { running:false, paused:false, mode:'survival', map:'neon', player:{x:2.5,y:2.5,a:0.1,hp:100}, enemies:[], score:0, kills:0, shots:0, hits:0, ammo:12, reserve:60, wave:1, timer:60, target:12, last:0, spawn:0, recoil:0, hurt:0, toastUntil:0, fireHeld:false, muted:true, pointerX:null, joystick:{x:0,y:0}, sound:null };
  let W=innerWidth,H=innerHeight,DPR=1;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const rand=(a,b)=>a+Math.random()*(b-a);
  function resize(){W=innerWidth;H=innerHeight;DPR=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);ctx.setTransform(DPR,0,0,DPR,0,0)}
  addEventListener('resize',resize);resize();
  const world=(x,y)=>{const m=maps[state.map].layout;const ix=Math.floor(x),iy=Math.floor(y);return iy<0||iy>=m.length||ix<0||ix>=m[0].length||m[iy][ix]==='#'};
  function clearLine(x1,y1,x2,y2){const n=Math.ceil(Math.hypot(x2-x1,y2-y1)*8);for(let i=1;i<n;i++){const t=i/n;if(world(x1+(x2-x1)*t,y1+(y2-y1)*t))return false}return true}
  function choose(el, attr, value){document.querySelectorAll(el).forEach(b=>b.classList.toggle('selected',b.dataset[attr]===value))}
  document.querySelectorAll('.mode-card').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;choose('.mode-card','mode',state.mode)});
  document.querySelectorAll('.map-card').forEach(b=>b.onclick=()=>{state.map=b.dataset.map;choose('.map-card','map',state.map);$('top-map').textContent=maps[state.map].name});
  const show=(id,on)=>$(id).classList.toggle('hidden',!on);
  function start(){
    state.player={x:2.5,y:2.5,a:0.1,hp:100};state.enemies=[];state.score=0;state.kills=0;state.shots=0;state.hits=0;state.ammo=12;state.reserve=60;state.wave=1;state.timer=60;state.target=12;state.spawn=0;state.running=true;state.paused=false;state.recoil=0;state.hurt=0;
    $('hud-map').textContent=maps[state.map].name;$('wave').textContent='01';$('score').textContent='000000';$('health-fill').style.width='100%';$('health-value').textContent='100';$('ammo').textContent='12';$('objective').textContent=state.mode==='precision'?'ELIMINA 12 OBJETIVOS':'ELIMINA A LOS HOSTILES';$('timer').classList.toggle('hidden',state.mode!=='rush');$('timer').textContent='01:00';
    show('menu',false);show('pause-screen',false);show('result-screen',false);show('hud',true);canvas.style.opacity='1';document.body.classList.add('playing');
    const initial=state.mode==='precision'?4:5;for(let i=0;i<initial;i++)spawnEnemy();state.last=performance.now();requestAnimationFrame(loop);toast('¡HOSTILES DETECTADOS!');
  }
  $('start-btn').onclick=start;
  function pause(){if(!state.running)return;state.paused=!state.paused;show('pause-screen',state.paused);if(!state.paused){state.last=performance.now();requestAnimationFrame(loop)}}
  $('pause-btn').onclick=pause;$('resume-btn').onclick=pause;
  function backToMenu(){state.running=false;state.paused=false;show('hud',false);show('pause-screen',false);show('result-screen',false);show('menu',true);canvas.style.opacity='0';document.body.classList.remove('playing')}
  $('quit-btn').onclick=backToMenu;$('menu-btn').onclick=backToMenu;$('again-btn').onclick=start;
  function toast(text){$('toast').textContent=text;state.toastUntil=performance.now()+1500}
  function spawnEnemy(){
    const p=state.player;let x,y,tries=0;do{x=rand(1.3,14.7);y=rand(1.3,14.7);tries++}while(tries<100&&(world(x,y)||Math.hypot(x-p.x,y-p.y)<5||!clearLine(p.x,p.y,x,y)));
    if(world(x,y)){x=12.5;y=12.5}state.enemies.push({x,y,hp:state.mode==='precision'?1:2,speed:rand(.35,.52),phase:rand(0,7),hit:0,attack:rand(1.5,3.8),alive:true});
  }
