const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-dev-shm-usage'] });
  const errors = [];
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  await page.goto('http://localhost:3002');
  await page.waitForTimeout(200);
  const menuOverflow = await page.evaluate(() => document.documentElement.scrollWidth > innerWidth || document.documentElement.scrollHeight > innerHeight);
  const maps = ['neon', 'dune', 'frost'];
  const modes = ['survival', 'rush', 'precision'];
  const checks = [];
  for (let i = 0; i < maps.length; i++) {
    await page.locator(`[data-map="${maps[i]}"]`).click();
    await page.locator(`[data-mode="${modes[i]}"]`).click();
    await page.locator('#start-btn').click();
    await page.waitForTimeout(250);
    checks.push({ map: await page.locator('#hud-map').innerText(), mode: await page.locator('#objective').innerText(), timerVisible: await page.locator('#timer').isVisible(), joystick: await page.locator('#joystick').isVisible(), fire: await page.locator('#mobile-fire').isVisible() });
    if (i === 2) await page.screenshot({ path: '/tmp/opencode/nova-mobile.jpg', type: 'jpeg', quality: 72 });
    await page.locator('#pause-btn').click();
    if (!await page.locator('#pause-screen').isVisible()) throw new Error('Pause screen did not appear');
    await page.locator('#quit-btn').click();
  }
  await page.locator('[data-map="neon"]').click();
  await page.locator('[data-mode="rush"]').click();
  await page.locator('#start-btn').click();
  const ammoBefore = await page.locator('#ammo').innerText();
  await page.locator('#mobile-fire').click();
  const ammoAfter = await page.locator('#ammo').innerText();
  await page.locator('#mobile-reload').click();
  const ammoReloaded = await page.locator('#ammo').innerText();
  console.log(JSON.stringify({ menuOverflow, checks, ammoBefore, ammoAfter, ammoReloaded, errors }, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

